  throw new Error('Image Agent failed (chunk ' + (vars.chunkIndex + 1) + '/' + vars.totalChunks + '): ' + (inp.error || JSON.stringify(inp)).substring(0, 300));
let raw = (inp.output || '').trim();
if (raw.startsWith('__disk__:')) raw = fs.readFileSync(raw.slice(9), 'utf-8').trim();
const m = raw.match(/```(?:json)?\n?([\s\S]*?)```/);
if (m) raw = m[1].trim();
let manifest;
try { manifest = JSON.parse(raw); }
catch(e) {
  const s = raw.indexOf('{'), en = raw.lastIndexOf('}');
  if (s === -1 || en === -1) {
    const dbgPath = vars.projectDir + '/scripts/image_chunk_' + vars.chunkIndex + '_parse_failure_debug.txt';
    fs.writeFileSync(dbgPath, raw, 'utf-8');
    throw new Error('Cannot parse chunk manifest (no braces found). Saved raw to ' + dbgPath + '. First 500 chars: ' + raw.substring(0, 500));
  }
  try { manifest = JSON.parse(raw.substring(s, en + 1)); }
  catch(e2) {
    const dbgPath = vars.projectDir + '/scripts/image_chunk_' + vars.chunkIndex + '_parse_failure_debug.txt';
    fs.writeFileSync(dbgPath, raw, 'utf-8');
    throw new Error('Cannot parse chunk manifest even after brace-extraction: ' + e2.message + '. Full raw saved to ' + dbgPath + '. First 500 chars: ' + raw.substring(0,500));
  }
}
const prompts = manifest.image_prompts || [];
if (prompts.length < 1)
  throw new Error('Chunk ' + (vars.chunkIndex + 1) + ' returned 0 prompts. Output: ' + (inp.output || '').substring(0, 200));
fs.writeFileSync(vars.imageManifestChunkPath, JSON.stringify(manifest, null, 2), 'utf-8');
console.log('Chunk ' + (vars.chunkIndex + 1) + '/' + vars.totalChunks + ': ' + prompts.length + ' prompts saved');
return [{ json: { ...vars } }];

