// ── Verification gate (added 2026-06-08 — Cahokia scene_186 incident) ───────────
// The Video Agent self-reports total_video_scenes / manifest_stats.total_video_prompts,
// but a single-shot Haiku pass generating 77 detailed Veo prompts in one go can silently
// drop an entry mid-generation while still echoing back the count it RECORDED AT STEP 1
// (the input scene count) rather than what it actually emitted. That's exactly what
// happened on Cahokia: scene_186 vanished from video_prompts while the manifest still
// claimed 77/77 — a self-contradiction nothing downstream ever checked. Don't trust the
// agent's self-report; recompute the truth from media_timeline.json and fail loudly
// BEFORE a single dollar gets spent on Kie.ai generation or a multi-hour render runs
// for two hours around a hole nobody knew was there.
const timeline = vars.timeline || JSON.parse(fs.readFileSync(vars.mediaTimelinePath, 'utf-8'));
const expectedIds = new Set(
  (timeline.scenes || [])
    .filter(sc => sc.visual_type === 'video')
    .map(sc => sc.scene_id)
);
const actualIds = new Set((manifest.video_prompts || []).map(p => p.scene_id));

const missingIds = [...expectedIds].filter(id => !actualIds.has(id));
const extraIds   = [...actualIds].filter(id => !expectedIds.has(id));

if (missingIds.length > 0 || extraIds.length > 0) {
  const lines = [];
  lines.push('Video manifest verification FAILED — agent output does not match media_timeline.json.');
  lines.push(`  Expected ${expectedIds.size} video-type scene(s) from the timeline; manifest contains ${actualIds.size} prompt(s).`);
  if (missingIds.length) lines.push(`  MISSING from video_prompts (present in timeline, absent from manifest): ${missingIds.join(', ')}`);
  if (extraIds.length)   lines.push(`  UNEXPECTED in video_prompts (not a visual_type:"video" scene in the timeline): ${extraIds.join(', ')}`);
  lines.push(`  Manifest self-reported total_video_scenes=${manifest.total_video_scenes}, manifest_stats.total_video_prompts=${manifest.manifest_stats && manifest.manifest_stats.total_video_prompts} — DO NOT trust these numbers, they are the agent's own (incorrect) self-count.`);
  lines.push('  Re-run the Video Agent step before continuing. Do not proceed to video generation with this manifest — it will silently render as a black screen 1-2 hours from now.');
  throw new Error(lines.join('\n'));
}

// Recompute the self-reported counts from the verified array instead of trusting the
// agent's arithmetic — keeps the file internally consistent even if the agent's count
// drifts again in the future, without masking any actual missing/extra scenes (those
// would have already thrown above).
manifest.total_video_scenes = actualIds.size;
if (manifest.manifest_stats) manifest.manifest_stats.total_video_prompts = actualIds.size;

fs.writeFileSync(vars.videoManifestPath, JSON.stringify(manifest, null, 2), 'utf-8');
console.log(`video_manifest.json saved & verified: ${actualIds.size}/${expectedIds.size} video prompts match media_timeline.json scene-for-scene`);
return [{ json: { ...vars, videoManifest: manifest } }];

