const fs = require('fs');
const { execSync } = require('child_process');
const vars = $input.first().json;

const timeline = JSON.parse(fs.readFileSync(vars.mediaTimelinePath, 'utf-8'));
const stockDir = vars.projectDir + '/stocks/16x9';
const attrPath = vars.projectDir + '/scripts/stock_attribution.json';

if (!fs.existsSync(stockDir)) fs.mkdirSync(stockDir, { recursive: true });

const stockScenes = (timeline.scenes || []).filter(
  s => s.real_photo_preferred === true && !s.asset_path
);

console.log('Stock Sourcing: ' + stockScenes.length + ' scenes flagged for real photos');

// Only accept image file types — skip PDFs, SVGs with complex rendering, etc.
const IMAGE_EXTS = new Set(['.jpg', '.jpeg', '.png', '.gif', '.tif', '.tiff', '.webp']);

const attribution = [];
let sourced = 0, skipped = 0, failed = 0;

for (const scene of stockScenes) {
  const query   = scene.wikimedia_search_query;
  const sceneId = scene.scene_id;

  if (!query) { console.log('  ' + sceneId + ': no search query — skip'); skipped++; continue; }

  // 1. Search Wikimedia Commons (wget replaces curl — curl not available in Docker)
  //
  // Commons search behaves like a title match, not a semantic search, so long
  // descriptive queries return nothing. Measured against the live API 2026-08-10:
  //   "Derinkuyu underground city carved chambers architecture passages"  0 hits
  //   "Derinkuyu underground city"                                        5 hits
  // The first Derinkuyu run sourced 1 photo from 37 flagged scenes because of
  // this. Retry with progressively shorter prefixes instead of giving up on the
  // first miss.
  const qWords = String(query).split(/\s+/).filter(Boolean);
  const candidates = [query];
  if (qWords.length > 4) candidates.push(qWords.slice(0, 3).join(' '));
  if (qWords.length > 2) candidates.push(qWords.slice(0, 2).join(' '));

  let hits = [], usedQuery = query, searchErrored = false;
  for (const cand of candidates) {
    const searchUrl = 'https://commons.wikimedia.org/w/api.php?action=query&list=search' +
      '&srsearch=' + encodeURIComponent(cand) + '&srnamespace=6&srlimit=5&format=json';
    let searchResult;
    try {
      const raw = execSync('wget -qO- --user-agent "RuinsUntold/2.0" "' + searchUrl + '"', { timeout: 15000 }).toString();
      searchResult = JSON.parse(raw);
    } catch(e) {
      console.log('  ' + sceneId + ': search failed — ' + e.message);
      searchErrored = true;
      break;
    }
    const h = (searchResult.query && searchResult.query.search) ? searchResult.query.search : [];
    if (h.length) { hits = h; usedQuery = cand; break; }
    console.log('  ' + sceneId + ': no results for "' + cand + '"');
    try { execSync('sleep 1'); } catch(e) {}
  }
  if (searchErrored) { failed++; continue; }
  if (!hits.length) { skipped++; continue; }
  if (usedQuery !== query) console.log('  ' + sceneId + ': fell back to "' + usedQuery + '"');

  // Find first hit with an acceptable image extension
  let fileTitle = null;
  for (const hit of hits) {
    const ext = hit.title.substring(hit.title.lastIndexOf('.')).toLowerCase();
    if (IMAGE_EXTS.has(ext)) { fileTitle = hit.title; break; }
  }
  if (!fileTitle) {
    console.log('  ' + sceneId + ': no image results (top hits are PDFs or non-images)');
    skipped++; continue;
  }

  // Rate limit: small delay between API calls
  try { execSync('sleep 1'); } catch(e) {}

  // 2. Get imageinfo + thumburl at 1920px
  const infoUrl = 'https://commons.wikimedia.org/w/api.php?action=query' +
    '&titles=' + encodeURIComponent(fileTitle) + '&prop=imageinfo&iiprop=url|thumburl|size|extmetadata' +
    '&iiurlwidth=1920&format=json';

  let infoResult;
  try {
    const raw = execSync('wget -qO- --user-agent "RuinsUntold/2.0" "' + infoUrl + '"', { timeout: 15000 }).toString();
    infoResult = JSON.parse(raw);
  } catch(e) {
    console.log('  ' + sceneId + ': imageinfo failed — ' + e.message);
    failed++; continue;
  }

  const pages  = (infoResult.query && infoResult.query.pages) ? infoResult.query.pages : {};
  const page   = Object.values(pages)[0];
  const info   = page && page.imageinfo && page.imageinfo[0];
  if (!info) {
    console.log('  ' + sceneId + ': no imageinfo for ' + fileTitle);
    skipped++; continue;
  }

  const thumbUrl = info.thumburl || info.url;
  const width    = info.width  || 0;
  const height   = info.height || 0;
  const extmeta  = info.extmetadata || {};
  const author   = extmeta.Artist && extmeta.Artist.value
    ? extmeta.Artist.value.replace(/<[^>]+>/g, '')
    : 'Unknown';
  const license  = extmeta.LicenseShortName && extmeta.LicenseShortName.value
    ? extmeta.LicenseShortName.value
    : 'Unknown';
  const descUrl  = 'https://commons.wikimedia.org/wiki/' + encodeURIComponent(fileTitle);

  // Skip NC licenses — commercial conflict at monetization
  if (license.includes('NC')) {
    console.log('  ' + sceneId + ': skipping ' + fileTitle + ' — NC license (' + license + ')');
    skipped++; continue;
  }

  // 3. Download via thumbnail API (avoids Wikimedia CDN bot protection on direct files)
  const safeName  = fileTitle.replace('File:', '').replace(/[^a-zA-Z0-9._-]/g, '_');
  const rawPath   = stockDir + '/' + sceneId + '_raw_' + safeName;
  const finalPath = stockDir + '/' + sceneId + '_' + safeName.replace(/\.(jpg|jpeg|png|tif|tiff)$/i, '.jpg');

  try {
    execSync('wget -qO "' + rawPath + '" --user-agent "RuinsUntold/2.0" "' + thumbUrl + '"', { timeout: 30000 });
    const bytes = fs.statSync(rawPath).size;
    if (bytes < 10000) throw new Error('file too small (' + bytes + ' bytes — likely HTML error page)');
  } catch(e) {
    console.log('  ' + sceneId + ': download failed — ' + e.message);
    if (fs.existsSync(rawPath)) fs.unlinkSync(rawPath); // clean up partial download
    failed++; continue;
  }

  // 4. Convert to 16:9 1920x1080
  const isPortrait = height > width;
  const vfFilter   = isPortrait
    ? 'scale=1920:1080:force_original_aspect_ratio=decrease,pad=1920:1080:(ow-iw)/2:(oh-ih)/2:black'
    : 'scale=1920:1080:force_original_aspect_ratio=increase,crop=1920:1080';

  try {
    execSync('/usr/local/bin/ffmpeg -y -i "' + rawPath + '" -vf "' + vfFilter + '" -q:v 2 "' + finalPath + '" 2>/dev/null', { timeout: 30000 });
    fs.unlinkSync(rawPath); // clean up raw download
  } catch(e) {
    console.log('  ' + sceneId + ': ffmpeg conversion failed — ' + e.message);
    if (fs.existsSync(rawPath)) fs.unlinkSync(rawPath); // clean up raw on failure too
    failed++; continue;
  }

  // 5. Patch scene in timeline
  scene.asset_path   = finalPath;
  scene.stock_source = fileTitle + ' | ' + author + ' | ' + license + ' | ' + descUrl;

  attribution.push({
    scene_id:        sceneId,
    file:            finalPath.split('/').pop(),
    wikimedia_title: fileTitle,
    author,
    license,
    url:             descUrl,
    search_query:    usedQuery,
  });

  console.log('  ' + sceneId + ': OK ' + fileTitle + ' (' + license + ')');
  sourced++;

  // Rate limit between scenes
  try { execSync('sleep 2'); } catch(e) {}
}

// 6. Write updated timeline and attribution log
